import {make} from './factory.js';
export default [
make('A2',1,{t:'Was va were: kechagi holat',goal:'O‘tmishdagi joy va holatni aytasiz.',context:'Sinfdoshlar kechagi ekskursiya haqida gaplashadi.',rule:['To be ning o‘tgan shakli I/he/she/it bilan was, you/we/they bilan were. Yesterday, last week kabi vaqtlar o‘tmishni aniqlaydi.','Wasn’t va weren’t inkor; Was she …? yoki Were they …? savol. Bu savollarga did qo‘shilmaydi.','O‘tgan holatni harakat bilan aralashtirmang: We were tired — holat; We walked — harakat. Was tired va was walking boshqa tuzilmalar.'],pattern:'was / were; Was she there? No, she wasn’t.',ex:['We were at the museum yesterday.','I was tired after the trip.','Lola wasn’t late.','Were the rooms open?','Yes, they were.','The weather was sunny.'],v:['museum|muzey|/mjuːˈziːəm/|visit a museum','tired|charchagan|/ˈtaɪəd/|be tired','trip|safar|/trɪp/|a school trip','sunny|quyoshli|/ˈsʌni/|sunny weather'],read:'Yesterday our class was at a history museum. The weather was sunny, so we walked from the bus stop. Lola was early, but two students were late. The rooms were open, and the guide was friendly. There were old maps and pictures of the city. After the visit, we were tired but happy. The café wasn’t open, so we ate our lunch in the park. Today we are writing about the trip and comparing our favourite objects.',rq:[['Nega bog‘da tushlik qilishdi?','the café wasn’t open','the guide was late','there were no maps','The café wasn’t open — sabab.'],['Ekskursiyadan keyin qanday edi?','tired but happy','angry and hungry','bored','We were tired but happy.']],listen:'We were at the museum yesterday. Lola was early. Two students were late. The guide was friendly, but the café wasn’t open. We ate in the park.',lq:[['Nechta o‘quvchi kechikdi?','two','three','one','Two students were late.'],['Kafe ochiqmidi?','No','Yes','Only for the guide','Wasn’t open — inkor.']],table:[['Kechikkanlar soni','two'],['Tushlik joyi','park']],gap:'We ___ tired yesterday.|were',fix:'Did she was there?|Was she there?',mc:['I ___ at home last night.','was','were','am','I uchun o‘tmishda was.'],exit:[['They ___ at the museum.','were'],['She ___ late. (inkor)','wasn’t'],['___ you tired yesterday?','Were'],['Holatni bildiradigan gapni tanlang.','We were tired.','We were walk.','We did tired.','Were + sifat holatni aytadi.'],['Yesterday vaqtini tanlang.','past','future','always present','Yesterday kecha.']],wtask:'Kecha bo‘lgan joyingiz va holatingiz haqida qisqa xabar yozing.',write:'Yesterday I was at the museum with my class. The weather was sunny, and our guide was friendly. There were old maps in one room. I was interested in a picture of our city. After the visit, we were tired, but we were happy. The café wasn’t open, so our lunch was in the park.',speak:'Kecha qayerda bo‘lganingizni va qanday his qilganingizni ayting.',visual:'timeline'}),
make('A2',2,{t:'Past Simple: tugallangan ish va did',goal:'O‘tmishdagi tugallangan voqeani savol va inkor bilan ifodalaysiz.',context:'Oila dam olish kunida nima qilganini eslaydi.',rule:['Muntazam fe’llarga odatda -ed qo‘shiladi: visit → visited, play → played. Live → lived, study → studied imlosini farqlang.','Savol va inkorda did/didn’t + asosiy shakl: Did you visit? We didn’t visit. Did you visited noto‘g‘ri.','Past Simple tugallangan o‘tmish voqeasini aytadi. Yesterday va last Sunday kabi vaqt bilan ishlatiladi; vaqt ko‘rinmasa ham kontekst o‘tmishni belgilashi mumkin.'],pattern:'visited / Did you visit? / didn’t visit',ex:['We visited our grandparents.','I played football on Sunday.','She studied in the library.','Did you watch the film?','We didn’t stay late.','They arrived at six.'],v:['visit|tashrif buyurmoq|/ˈvɪzɪt/|visit grandparents','arrive|yetib kelmoq|/əˈraɪv/|arrive at six','stay|qolmoq|/steɪ/|stay late','grandparents|bobo va buvi|/ˈɡrænpeərənts/|our grandparents'],read:'Last Sunday we visited our grandparents in a nearby village. We arrived at ten and helped in the garden. My brother played football with our cousins. I stayed inside for a short time and listened to my grandmother’s stories. After lunch, we watched an old film. We didn’t stay late because school started the next morning. At home, I wrote three new words from the film in my notebook. Did you have a quiet Sunday too?',rq:[['Nega kechgacha qolishmadi?','school started the next morning','the film was boring','the garden was closed','Because school started the next morning.'],['So‘zlovchi kimning hikoyasini tingladi?','grandmother’s','brother’s','teacher’s','My grandmother’s stories.']],listen:'We visited our grandparents last Sunday. We arrived at ten and helped in the garden. My brother played football. We didn’t stay late because we had school on Monday.',lq:[['Qachon yetib kelishdi?','ten','six','twelve','Arrived at ten.'],['Aka yoki uka nima qildi?','played football','watched birds','studied English','My brother played football.']],table:[['Kun','Sunday'],['Kelish soati','ten']],gap:'Did you ___ the film? (watch)|watch',fix:'We didn’t stayed late.|We didn’t stay late.',mc:['O‘tgan savolni tanlang.','Did you visit the village?','Did you visited the village?','Do you visited the village?','Did + visit asosiy shakl.'],exit:[['Yesterday I ___ football. (play)','played'],['She ___ English. (study)','studied'],['Did they ___ at six? (arrive)','arrive'],['Inkorni tanlang.','We didn’t stay.','We didn’t stayed.','We don’t stayed.','Didn’t shaklni o‘zi o‘tmishga olib o‘tadi.'],['Visit ning muntazam o‘tgan shakli?','visited','visitted','visiting','Visit → visited.']],wtask:'Dam olish kunidagi uch voqeani tartib bilan yozing. Bitta qilmagan ishingizni ham ayting.',write:'Last Saturday I visited my cousins. We played a board game and helped prepare lunch. After lunch, we watched a short film. I liked the story, but my cousin preferred the music. We didn’t stay outside late. In the evening, I studied English for half an hour and wrote a message to my friend.',speak:'Sherigingizdan Did you …? bilan dam olish kuni haqida so‘rang.',visual:'timeline'}),
make('A2',3,{t:'Noto‘g‘ri fe’llar va o‘tgan hikoya',goal:'Go/went, see/saw, buy/bought bilan qisqa voqea aytasiz.',context:'Bozordagi yo‘qolgan daftarni topish voqeasi eslanadi.',rule:['Noto‘g‘ri fe’llar -ed qoidasi bilan yasalmaydi: go → went, see → saw, buy → bought, take → took. Shaklni kontekst bilan o‘rganing.','Savolda va inkorda yana asosiy shaklga qaytamiz: Did you go? I didn’t buy. Did you went emas.','First, then, after that, finally voqealarni bog‘laydi. Har gapda o‘tmishdagi kim nima qilganini aniq ko‘rsating.'],pattern:'go → went; see → saw; buy → bought; Did you go?',ex:['I went to the market.','She saw a red notebook.','We bought some fruit.','He took the bus home.','Did you find your bag?','I didn’t buy a new pen.'],v:['market|bozor|/ˈmɑːkɪt/|go to the market','find|topmoq|/faɪnd/|find a bag','fruit|meva|/fruːt/|buy some fruit','finally|nihoyat|/ˈfaɪnəli/|finally find it'],read:'I went to the market with my father on Saturday. First, we bought some fruit. Then I saw a small book stall and looked at the notebooks. I took my red notebook out of my bag to check its size. After that, we went to the bus stop. I couldn’t find my notebook. We walked back to the stall, and the seller gave it to me. Finally, we took the bus home. I didn’t buy a new notebook because I found my old one.',rq:[['Daftar qayerda qolgan edi?','at the book stall','on the bus','at home','Qaytib sotuvchidan olishadi.'],['Nega yangi daftar olmadi?','he found the old one','the market was closed','he had no bag','Because I found my old one.']],listen:'I went to the market on Saturday. We bought fruit. I left my notebook at a book stall. The seller gave it back to me. Finally, we took the bus home.',lq:[['Kim daftarni qaytardi?','the seller','the driver','a cousin','The seller gave it back.'],['Uyga qanday qaytishdi?','by bus','on foot','by bicycle','Took the bus home.']],table:[['Yo‘qolgan buyum','notebook'],['Qaytargan odam','seller']],gap:'Yesterday we ___ fruit. (buy)|bought',fix:'Did you went home?|Did you go home?',mc:['See ning o‘tgan shakli qaysi?','saw','seed','seeed','See → saw.'],exit:[['Go ning o‘tgan shakli?','went'],['Take ning o‘tgan shakli?','took'],['I didn’t ___ a pen. (buy)','buy'],['Savolni tanlang.','Did you see it?','Did you saw it?','Do you saw it?','Did + see.'],['Buy ning o‘tgan shakli?','bought','buyed','buied','Buy → bought.']],wtask:'Bir buyumni topgan yoki bir joyga borgan voqeangizni first/then/finally bilan yozing.',write:'On Sunday I went to the park with my sister. First, we bought some water. Then we saw a small dog near a tree. Its owner was looking for it. We told the owner where the dog was. Finally, she found it and thanked us. We took some photos and went home before lunch.',speak:'Bitta o‘tgan voqeani ayting; sherigingiz kamida ikkita tafsilotni so‘rasin.'}),
make('A2',4,{t:'Past Continuous va uzilgan harakat',goal:'O‘tmishdagi davom etayotgan ishga qisqa voqea kirishini ko‘rsatasiz.',context:'O‘quvchi uy vazifasi qilayotganda elektr o‘chib qoladi.',rule:['Was/were + -ing o‘tmishdagi ma’lum paytda davom etayotgan harakatni bildiradi: I was reading at eight.','Past Simple qisqa kiruvchi voqeani beradi: I was reading when the lights went out. Ikki shakl bir hikoyada turli vazifaga ega.','While ko‘pincha davom etayotgan ikki ishni bog‘laydi. When va while ni faqat bitta zamonga qamalgan avtomatik signal deb olmang; ma’noni kuzating.'],pattern:'was/were + -ing … when + Past Simple',ex:['I was reading at eight.','The lights went out.','She was writing when I called.','We were talking while Ali was drawing.','Were you sleeping?','They weren’t watching TV.'],v:['lights|chiroqlar|/laɪts/|the lights went out','call|qo‘ng‘iroq qilmoq|/kɔːl/|call a friend','while|… paytida|/waɪl/|while I was reading','suddenly|to‘satdan|/ˈsʌdənli/|suddenly stop'],read:'At eight yesterday evening, I was doing my homework. My sister was reading in the same room. Suddenly, the lights went out. We stopped working and looked outside. Our neighbours’ lights were off too. While my father was checking a torch, I called my friend. She was studying when I called, but her lights were working. After twenty minutes, our lights came back on. We finished our homework and went to bed a little later than usual.',rq:[['Chiroq o‘chganda so‘zlovchi nima qilayotgan edi?','doing homework','sleeping','walking outside','Was doing homework — fon harakat.'],['Chiroq qancha vaqtdan keyin qaytdi?','twenty minutes','two hours','five minutes','After twenty minutes.']],listen:'I was doing homework at eight. My sister was reading. Suddenly, the lights went out. I called my friend, but her lights were working. Our lights came back after twenty minutes.',lq:[['Singlisi nima qilayotgan edi?','reading','sleeping','cooking','Was reading deyiladi.'],['Chiroq qaytish vaqti?','twenty minutes','ten minutes','an hour','After twenty minutes.']],table:[['Soat','eight'],['Kutish','twenty minutes']],gap:'We ___ talking when he arrived.|were',fix:'I was read at eight.|I was reading at eight.',mc:['Fon harakatni tanlang.','I was reading when she called.','I did reading when she call.','I were read when she called.','Was + reading davom etayotgan fon.'],exit:[['She ___ writing when I called.','was'],['They were ___ TV. (watch)','watching'],['I was reading ___ the lights went out.','when'],['Qisqa kiruvchi voqea qaysi?','the lights went out','I was reading','she was writing','Went out Past Simpleda qisqa voqea.'],['We bilan davomli o‘tmish yordamchisi?','were','was','did','We were + -ing.']],wtask:'Bir ish qilayotgan paytingizda boshqa voqea yuz bergan hikoya yozing.',write:'Yesterday I was studying in the library when my phone rang. My brother was waiting outside. He didn’t have his keys, so he asked me for help. While I was putting my books away, the librarian asked me to speak quietly. I said sorry, left the room, and gave my brother the keys.',speak:'What were you doing at eight? savoliga javob bering va bitta qisqa voqea qo‘shing.',visual:'timeline'}),
make('A2',5,{t:'Kelajak: will va going to',goal:'Reja, ko‘rinib turgan taxmin va shu paytdagi qarorni farqlaysiz.',context:'Sinf dam olish kuni kichik sayrni rejalashtiradi.',rule:['Be going to oldindan tuzilgan niyat yoki hozirgi dalilga tayangan taxminni ifodalaydi: We’re going to visit the park.','Will ko‘pincha hozir qabul qilingan qaror, taklif va umumiy taxmin uchun: I’ll carry the bag. Shakllar ayrim vaziyatlarda bir-biriga yaqin bo‘lishi mumkin.','Going to uchun am/is/are kerak. Will dan keyin asosiy fe’l keladi. Aniq tashkil qilingan kelajak uchrashuvida Present Continuous ham ishlatiladi.'],pattern:'We are going to … / I will … / We are meeting on Saturday.',ex:['We are going to visit the park.','I’ll carry the bag.','Look at the clouds. It is going to rain.','I think the trip will be fun.','We are meeting at nine.','She isn’t going to stay late.'],v:['plan|reja|/plæn/|make a plan','cloud|bulut|/klaʊd/|dark clouds','carry|ko‘tarmoq|/ˈkæri/|carry a bag','rain|yomg‘ir yog‘moq|/reɪn/|going to rain'],read:'Our class is going to visit a park on Saturday. We made the plan yesterday and are meeting at nine near school. Lola is going to bring water. Ali sees her heavy bag and says, “I’ll carry it.” The teacher looks at the dark clouds and thinks it is going to rain. We decide to take light raincoats. I think the trip will be interesting because a guide will show us different trees. If the weather is very bad, we will visit the indoor museum instead.',rq:[['Oldindan tuzilgan reja nima?','visit the park','carry Lola’s bag','cancel school','We made the plan yesterday.'],['Yomg‘ir taxmini qaysi dalilga asoslangan?','dark clouds','a broken bag','a long bus ride','Look at the dark clouds.']],listen:'We are going to visit the park on Saturday. We are meeting at nine. Lola will bring water. Look at those clouds! It is going to rain, so I’ll bring a raincoat too.',lq:[['Uchrashuv nechada?','nine','ten','eight','Meeting at nine.'],['Nima olib keladi?','a raincoat','a computer','a blanket','I’ll bring a raincoat.']],table:[['Kun','Saturday'],['Soat','nine']],gap:'She ___ going to bring water.|is',fix:'I will carrying the bag.|I will carry the bag.',mc:['Ko‘rinib turgan dalil bilan taxminni tanlang.','Look at the clouds. It’s going to rain.','It raining yesterday.','We rain clouds.','Dark clouds hozirgi dalil.'],exit:[['We ___ going to visit the park.','are'],['I will ___ the bag.','carry'],['We are ___ at nine. (meet)','meeting'],['Shu paytdagi taklifga mos gap?','I’ll help you.','I helped yesterday.','I am help you.','Will bilan hozirgi taklif.'],['Going to dan oldin nima kerak?','am/is/are','did','have always','Going to ning be qismi kerak.']],wtask:'Dam olish kuni rejasi, bitta taklif va ob-havo taxminini yozing.',write:'We are going to visit our cousins on Sunday. We are meeting at the bus stop at ten. I am going to bring a cake. My sister has a heavy bag, so I’ll carry it. I think we will have a good day, but the clouds look dark, so I’m going to take a raincoat.',speak:'Sherigingiz bilan sayr rejasini kelishing va bir yordam taklif qiling.',visual:'timeline'}),
make('A2',6,{t:'Taqqoslash va eng yuqori daraja',goal:'Ikki yoki ko‘p variantni comparative/superlative bilan solishtirasiz.',context:'O‘quvchilar klub uchun qaysi xona qulayligini tanlaydi.',rule:['Qisqa sifatlarda -er va the -est: small → smaller → the smallest. Happy → happier, big → bigger.','Uzunroq sifatlarda more/the most: more comfortable. Good → better → the best, bad → worse → the worst.','Ikki narsani than bilan taqqoslaymiz. Guruh ichida the tallest in the class kabi ibora ishlatiladi. More better shakli ikki marta taqqoslashdir.'],pattern:'smaller than / more comfortable than / the best in …',ex:['Room 2 is smaller than Room 5.','This chair is more comfortable.','Lola is taller than Ali.','This is the best place to study.','The library is the quietest room.','My bag is heavier than yours.'],v:['comfortable|qulay|/ˈkʌmftəbəl/|a comfortable chair','quiet|sokin|/ˈkwaɪət/|the quietest room','heavy|og‘ir|/ˈhevi/|a heavier bag','choose|tanlamoq|/tʃuːz/|choose the best room'],read:'We need a room for our reading club. Room 2 is smaller than Room 5, but it has more comfortable chairs. Room 5 is brighter because it has three windows. The library is the quietest place in the school, but it closes early. We choose Room 5 for Friday meetings because it is large enough for twelve students. It isn’t the quietest room, so we agree to speak softly. For individual reading, we think the library is still the best choice.',rq:[['Nega Room 5 tanlandi?','it is large enough','it has the best chairs','it is the smallest','Large enough for twelve students.'],['Eng sokin joy qaysi?','the library','Room 5','Room 2','The library is the quietest.']],listen:'Room 2 is smaller than Room 5. Room 5 is brighter, but Room 2 has more comfortable chairs. The library is the quietest place. We choose Room 5 because it has enough space.',lq:[['Qaysi xona yorug‘roq?','Room 5','Room 2','Room 1','Room 5 is brighter.'],['Qayerdagi stullar qulayroq?','Room 2','Room 5','outside','Room 2 has more comfortable chairs.']],table:[['Yorug‘roq xona','5'],['Eng sokin joy','library']],gap:'This room is ___ than that one. (small)|smaller',fix:'This is more better.|This is better.',mc:['Good ning eng yuqori shakli?','the best','the goodest','the most good','Good → better → the best.'],exit:[['Tall ning comparative shakli?','taller'],['Happy ning comparative shakli?','happier'],['Good ning comparative shakli?','better'],['To‘g‘ri taqqoslashni tanlang.','quieter than','more quieter than','quiet than','Bir marta comparative yasaladi.'],['Uzun sifatga mos shakl?','more comfortable','comfortabler','most comfortable than','Comparative more comfortable.']],wtask:'Ikki o‘qish joyini taqqoslang va eng mosini sabab bilan tanlang.',write:'Our library is quieter than the café. It also has more books. The café is warmer and has more comfortable chairs, but it can be busy. For homework, I think the library is the best place because I can concentrate. For talking with friends after school, the café is a better choice.',speak:'Ikki xona rasmini taqqoslab birini klub uchun tanlang.',visual:'compare'}),
make('A2',7,{t:'Sifat, ravish va too/enough',goal:'Narsa qanday va ish qanday bajarilishini ajratasiz.',context:'Yo‘l ko‘rsatma va xona qulayligi muhokama qilinadi.',rule:['Sifat ot yoki to be dan keyin: a careful driver, the room is quiet. Ravish harakatni tasvirlaydi: drives carefully.','Ko‘p ravishlar -ly oladi, ammo good → well, fast → fast istisno. She speaks well — yaxshi gapiradi.','Too + sifat kerakdan ortiqlik; sifat + enough yetarlilik: too small, big enough. Enough + ot: enough space.'],pattern:'a careful driver → drives carefully; too small / big enough',ex:['She speaks slowly.','He is a careful driver.','He drives carefully.','This room is too small.','The bag is light enough.','We have enough space.'],v:['careful|ehtiyotkor|/ˈkeəfəl/|a careful driver','slowly|sekin|/ˈsləʊli/|speak slowly','space|bo‘sh joy|/speɪs/|enough space','light|yengil|/laɪt/|a light bag'],read:'Our club wants to show a short film. The first room is too small for twenty people. The second room is big enough, but the sound is too quiet. Ali speaks slowly when he explains the problem. The teacher asks us to check the speakers carefully. After we move them, everyone can hear well. We have enough chairs and enough space. We do not turn the sound up too much because another class is studying next door.',rq:[['Birinchi xonaning muammosi nima?','too small','too bright','too quiet','Too small for twenty people.'],['Spikerlar ko‘chirilgach nima o‘zgardi?','everyone can hear well','the film got shorter','chairs disappeared','Hear well — natija.']],listen:'The first room is too small. The second is big enough. Please speak slowly and check the speakers carefully. Now everyone can hear well. We have enough chairs.',lq:[['Qaysi xona yetarlicha katta?','the second','the first','neither','The second is big enough.'],['Qanday gapirish so‘raladi?','slowly','loudly','angrily','Please speak slowly.']],table:[['Yetarli katta xona','second'],['Gapirish usuli','slowly']],gap:'He drives ___. (careful)|carefully',fix:'She speaks good.|She speaks well.',mc:['Yetarli kattalikni tanlang.','big enough','enough big','too enough big','Enough sifatdan keyin.'],exit:[['She speaks ___. (slow)','slowly'],['a ___ driver (careful)','careful'],['We have ___ space. (yetarli)','enough'],['Too small ma’nosi?','smaller than needed','a good small size','large enough','Too kerakdan ortiq darajani bildiradi.'],['Good ning ravish shakli?','well','goodly','betterly','Good → well.']],wtask:'Bir xonaning muammolari va yechimini too/enough hamda ikki ravish bilan yozing.',write:'Our first room was too small for the group. We moved to a bigger room with enough chairs. The teacher spoke slowly and explained the task clearly. The room was quiet enough for listening. We checked the audio carefully and did not play it too loudly because students were working next door.',speak:'Bir vazifa uchun joy qulayligini baholang va qanday ishlash kerakligini ayting.',visual:'compare'}),
make('A2',8,{t:'A few, few, a little va little',goal:'Miqdor kamligi va yetarliligini ma’noga qarab ifodalaysiz.',context:'Sayrga qolgan vaqt va oziq-ovqat baholanadi.',rule:['A few ko‘plik sanaladigan ot bilan oz bo‘lsa ham bor degani. Few juda kam, ko‘pincha yetarli emas ma’nosini beradi.','A little sanalmaydigan ot bilan ozgina bor; little juda kamligini ko‘rsatadi. A little water va little water bir xil ohang emas.','Miqdor aniq raqam bo‘lmasligi mumkin. Matndagi vazifa va so‘zlovchining bahosiga qarab yetarlilikni tushuning.'],pattern:'a few apples / few apples; a little time / little time',ex:['We have a few apples.','There are few buses today.','I have a little time.','We have little water left.','There are a few seats available.','She adds a little milk.'],v:['left|qolgan|/left/|water left','available|mavjud, bo‘sh|/əˈveɪləbəl/|seats available','seat|o‘rindiq|/siːt/|a few seats','add|qo‘shmoq|/æd/|add a little milk'],read:'Our picnic starts in half an hour. We have a few apples, so each small group can share one. There is a little water in the first bottle, but it is not enough for everyone. Ali buys two more bottles. There are few buses on Sunday, so we decide to walk to the nearby park. We still have a little time to check our bags. After the trip, very little rubbish is left because everyone uses reusable cups.',rq:[['Nega piyoda borishadi?','there are few buses','they have many bags','the park is closed','Few buses — avtobuslar kam.'],['Nega yana suv olinadi?','the first bottle is not enough','everyone dislikes apples','there is too much water','Not enough for everyone — maqsad.']],listen:'We have a few apples and a little water. There are few buses today. Ali will buy two more bottles, and then we can walk to the park. We still have a little time.',lq:[['Ali nechta idish oladi?','two','three','one','Two more bottles.'],['Yo‘l qanday bo‘ladi?','walking','by train','by taxi','Walk to the park.']],table:[['Yangi idishlar','two'],['Yo‘l usuli','walking']],gap:'We have a ___ apples.|few',fix:'I have a few water.|I have a little water.',mc:['Water bilan qaysi miqdor mos?','a little','a few','many','Water sanalmaydigan ot.'],exit:[['a ___ seats','few'],['a ___ milk','little'],['few ___ (bus, ko‘plik)','buses'],['Few va a few bir xil ohangmi?','No','Yes','Always','Few ko‘proq kamlik muammosini ta’kidlaydi.'],['A little time nimani bildiradi?','some time','many separate times','no time at all','Oz bo‘lsa ham vaqt bor.']],wtask:'Sayrga tayyorgarlik haqida kam, yetarli va yetmaydigan miqdorlarni yozing.',write:'We have a few sandwiches for the group and a little fruit. There is little water left, so we need more bottles. Few shops are open on Sunday. We still have a little time before the trip. I will check the nearest shop while my friend prepares the reusable cups.',speak:'Miqdorni shunchaki sanamang; bor narsa yetarlimi, shuni ham ayting.',visual:'menu'}),
make('A2',9,{t:'Majburiyat, taqiq va erkin tanlov',goal:'Mustn’t va don’t have to farqini vaziyat orqali tushuntirasiz.',context:'Maktab ustaxonasining qoidalari o‘qiladi.',rule:['Have to tashqi qoida yoki vaziyat sabab zarur ishni bildiradi. Must gapiruvchining kuchli talabi bo‘lishi mumkin.','Mustn’t — taqiq; don’t have to — shart emas, ammo mumkin. Ularni bir ma’noda ishlatmang.','Savolda do/does + have to; o‘tgan majburiyatda had to. Mustdan keyin fe’lning asosiy shakli keladi.'],pattern:'have to wear / mustn’t touch / don’t have to bring',ex:['We have to wear safety glasses.','You must not touch the hot tool.','You do not have to bring paper.','Does she have to arrive early?','Yesterday we had to clean the tables.','You can bring your own notebook.'],v:['rule|qoida|/ruːl/|follow a rule','tool|asbob|/tuːl/|a hot tool','required|talab etilgan|/rɪˈkwaɪəd/|required equipment','optional|ixtiyoriy|/ˈɒpʃənəl/|an optional notebook'],read:'Our school workshop has clear rules. Everyone has to wear safety glasses near the tools. Students must not touch a hot tool, even when the teacher is close. We do not have to bring paper because the school provides it. A notebook is optional, but it is useful for planning. Yesterday we had to clean the tables before the next group arrived. A new student thought that “do not have to bring a notebook” meant notebooks were forbidden. The teacher explained that it was a choice, not a ban. We read the rules again and separated necessary actions from choices. Clear language helps us work together without confusion.',rq:[['Daftar olib kelish mumkinmi?','Yes, it is optional','No, it is forbidden','Only yesterday','Shart emas degani taqiq emas.'],['Nima taqiqlangan?','touching a hot tool','wearing glasses','bringing a notebook','Must not touch taqiq.']],listen:'Welcome to the workshop. You have to wear safety glasses. You must not touch a hot tool. You do not have to bring paper. The school provides it. You can bring a notebook if you want.',lq:[['Qog‘ozni kim beradi?','the school','the student only','nobody','School provides it.'],['Ko‘zoynak zarurmi?','Yes','No','Only at home','Have to wear.']],table:[['Zarur jihoz','safety glasses'],['Maktab beradigan narsa','paper']],gap:'Yesterday we ___ to clean the tables.|had',fix:'She have to arrive early.|She has to arrive early.',mc:['Shart emas, lekin mumkin degan gap?','You do not have to bring a notebook.','You must not bring a notebook.','You cannot bring a notebook.','Don’t have to erkin tanlov.'],exit:[['She ___ to wear glasses.','has'],['We ___ not touch a hot tool.','must'],['___ he have to arrive early?','Does'],['Taqiq qaysi?','must not','do not have to','may','Must not taqiq.'],['Yesterday we ___ to clean.','had']],wtask:'Kutubxona yoki ustaxona uchun zarur ish, taqiq va ixtiyoriy ishni ajratib qoida yozing.',write:'In our workshop, we have to wear safety glasses near the tools. We must not touch a hot tool or leave a bag in the walking area. We do not have to bring paper because the school provides it. A notebook is optional. Yesterday we had to clean the tables before leaving. Please read the rules and ask the teacher if a choice is unclear.',speak:'Yangi o‘quvchiga bir majburiyat, bir taqiq va bir ixtiyoriy tanlovni tushuntiring.'}),
make('A2',10,{t:'Should va odobli so‘rovlar',goal:'Maslahat berasiz va yordamni muloyim so‘raysiz.',context:'Do‘stingiz imtihon oldidan rejasi bo‘yicha yordam so‘raydi.',rule:['Should + asosiy fe’l maslahat: You should rest. Shouldn’t qilmaslik tavsiyasi. Bu har doim majburiy qoida emas.','Could you …? va Would you …? kundalik odobli so‘rov. Could bu yerda o‘tgan zamon haqida emas.','Can I …? ruxsat, Could you …? suhbatdoshning yordam amali. Please odobni kuchaytiradi, lekin ohang ham muhim.'],pattern:'You should … / Could you …, please? / Would you mind + -ing?',ex:['You should take a short break.','You shouldn’t study all night.','Could you explain this word, please?','Can I borrow your dictionary?','Would you help me with the plan?','You should drink some water.'],v:['break|tanaffus|/breɪk/|take a break','explain|tushuntirmoq|/ɪkˈspleɪn/|explain a word','borrow|vaqtincha olmoq|/ˈbɒrəʊ/|borrow a dictionary','rest|dam olmoq|/rest/|get some rest'],read:'Ali has an English test tomorrow. He wants to study all night, but Lola says he should make a short plan and get some rest. Ali asks, “Could you explain this exercise, please?” Lola shows him one example, then asks him to try the next question himself. He borrows her dictionary and checks two words. They take a short break after twenty minutes. Ali feels more confident because he understands the task instead of simply copying the answers.',rq:[['Lola nimani tavsiya qiladi?','a short plan and rest','studying all night','copying every answer','Should make a short plan and get rest.'],['Ali nega ishonchliroq bo‘ldi?','he understood the task','he saw tomorrow’s test','he finished school','Understands the task instead of copying.']],listen:'You should take a short break, Ali. You shouldn’t study all night. Could you show me the exercise? We can do one example together, then you should try the next question yourself.',lq:[['Nima tavsiya qilinmaydi?','studying all night','taking a break','trying a question','Shouldn’t study all night.'],['Keyingi savolni kim bajaradi?','Ali himself','Lola alone','the teacher','Try the next question yourself.']],table:[['Tavsiya','break'],['Keyingi ish','try the next question']],gap:'You should ___ a break. (take)|take',fix:'Could you to help me?|Could you help me?',mc:['Odobli so‘rovni tanlang.','Could you explain this, please?','You must explain now!','Explain me you?','Could you … please? so‘rov.'],exit:[['You ___ rest. (maslahat)','should'],['Could you ___ me?','help'],['You shouldn’t ___ all night.','study'],['Could you bu yerda albatta o‘tmishmi?','No','Yes','Always','Could muloyimlikni ham ifodalaydi.'],['Should dan keyin shakl?','base verb','verb + s','to + verb','Should take.']],wtask:'Testga tayyorlanayotgan do‘stingizga uch tavsiya va bitta odobli so‘rov yozing.',write:'Hi Ali, you should make a short plan for your test. You shouldn’t study all night because you need rest. Try one exercise, check the explanation, and take a break. Could you send me the question you find difficult, please? I can explain an example, but you should write your own answer so that you really learn.',speak:'Maslahat so‘rang, ikkita tavsiya bering va bir odobli so‘rovga javob bering.',visual:'dialogue'}),
make('A2',11,{t:'Present Perfect: tajriba va hozirgi natija',goal:'Aniq tugallangan vaqt aytilmaganda tajriba yoki natijani ifodalaysiz.',context:'Sinf ko‘rgazma uchun qilingan ishlarni tekshiradi.',rule:['Have/has + past participle: I have finished, she has seen. Noto‘g‘ri fe’lning uchinchi shakli har doim ikkinchi bilan bir xil emas: went → gone.','Present Perfect o‘tmish bilan hozir o‘rtasidagi aloqani ko‘rsatadi. I have lost my key — hozir kalit yo‘q.','Yesterday kabi tugallangan vaqt aniq bo‘lsa Past Simple: I lost it yesterday. Present Perfect uchun faqat signal so‘zga emas, ma’noga tayaning.'],pattern:'have/has + V3; have finished / has seen',ex:['I have finished the poster.','She has seen this film.','We have visited Bukhara.','He has lost his key.','Have you tried this activity?','They haven’t started yet.'],v:['finish|tugatmoq|/ˈfɪnɪʃ/|finish a poster','lose|yo‘qotmoq|/luːz/|lose a key','try|sinab ko‘rmoq|/traɪ/|try an activity','key|kalit|/kiː/|a house key'],read:'Our class has prepared a small exhibition. I have finished the poster, and Lola has chosen the pictures. Ali has visited Bukhara, so he can explain one photo of the city. We haven’t put the labels on the wall yet. The teacher asks if we have checked all the names. I have lost my pencil, so I need to borrow one now. We finished the largest picture yesterday, but there is still work to do today.',rq:[['Nima hali qilinmagan?','putting labels on the wall','choosing pictures','finishing the poster','Haven’t put labels … yet.'],['Ali nima uchun rasmni tushuntira oladi?','he has visited Bukhara','he painted it yesterday','he has a key','Visited Bukhara tajribasi bor.']],listen:'I have finished the poster. Lola has chosen the pictures. Ali has visited Bukhara. We haven’t put the labels on the wall yet. Have you checked all the names?',lq:[['Rasmlarni kim tanlagan?','Lola','Ali','the guide','Lola has chosen.'],['Yorliqlar devordami?','not yet','all of them','since Monday','Haven’t … yet.']],table:[['Tayyor ish','poster'],['Ali ko‘rgan shahar','Bukhara']],gap:'She ___ seen this film.|has',fix:'I have went there.|I have gone there.',mc:['Hozirgi natijani tanlang.','I have lost my key, so I can’t open the door.','I have lose my key.','I have lost yesterday my key (finished time).','Have + lost hozirgi muammo bilan bog‘langan.'],exit:[['I ___ finished.','have'],['She has ___ it. (see)','seen'],['We haven’t ___ yet. (start)','started'],['Kecha bilan mos shaklni tanlang.','I finished it yesterday.','I have finished it yesterday.','I has finished yesterday.','Tugallangan vaqt Past Simple.'],['Go ning V3 shakli?','gone','went','goed','Go/went/gone.']],wtask:'Loyiha uchun allaqachon qilingan va hali qilinmagan ishlarni yozing.',write:'We have prepared most of our exhibition. I have finished the main poster, and my friend has chosen three photos. We have checked the city names, but we haven’t written all the labels yet. Ali has visited the place in one photo, so he can explain it. We need to finish the labels before Friday.',speak:'Have you ever …? bilan ikki tajribani so‘rang; natijani misol bilan tushuntiring.',visual:'timeline'}),
make('A2',12,{t:'Ever, never, just, already va yet',goal:'Tajriba va ishning tugash holatini aniqlashtirasiz.',context:'Ekskursiyaga tayyorgarlikning so‘nggi ishlari tekshiriladi.',rule:['Ever savollarda biror marta tajriba bo‘lganini, never esa hech qachon bo‘lmaganini aytadi: Have you ever flown?','Just hozirgina, already allaqachon, yet hali/gacha ma’noda inkor va savolda ko‘p uchraydi. Have just finished; haven’t finished yet.','Just/already ko‘pincha yordamchi bilan V3 orasida, yet odatda gap oxirida. Never bilan qo‘shimcha not ishlatilmaydi.'],pattern:'have just finished / have already packed / haven’t called yet',ex:['Have you ever visited Khiva?','I have never flown.','She has just arrived.','We have already packed our bags.','He hasn’t called yet.','Have you bought the tickets yet?'],v:['pack|joylamoq|/pæk/|pack a bag','fly|uchmoq|/flaɪ/|fly in a plane','already|allaqachon|/ɔːlˈredi/|already packed','yet|hali, shu vaqtgacha|/jet/|not yet'],read:'Lola has just arrived at school. Our group has already packed the maps and notebooks for the trip. Ali hasn’t called the bus company yet, so the teacher asks him to do it now. Most students have never visited Khiva. Aziz has been there once, but he has never travelled there with his classmates. The teacher asks, “Have you bought your tickets yet?” Everyone has a ticket except one student, who goes to the office to collect it.',rq:[['Ali nima qilmagan?','called the bus company','packed maps','arrived at school','Hasn’t called … yet.'],['Ko‘pchilik Khivaga borganmi?','No','Yes, many times','Only yesterday','Most students have never visited.']],listen:'I have just arrived. We have already packed the maps. Ali hasn’t called the bus company yet. Have you bought your ticket yet? Most students have never visited Khiva.',lq:[['Xaritalar tayyormi?','Yes','Not yet','They are lost','Already packed.'],['Qo‘ng‘iroq qilinganmi?','Not yet','Already','Just now','Hasn’t called yet.']],table:[['Tayyor buyumlar','maps'],['Bormagan shahar','Khiva']],gap:'She has ___ arrived. (hozirgina)|just',fix:'I haven’t never flown.|I have never flown.',mc:['Inkor gap oxiriga mos so‘z?','yet','already always','ever never','Haven’t called yet.'],exit:[['Have you ___ visited Khiva?','ever'],['I have ___ flown. (hech qachon)','never'],['He hasn’t called ___.','yet'],['Hozirgina kelganini tanlang.','She has just arrived.','She just has arriving.','She has arrive just.','Have/has + just + V3.'],['Allaqachon degani?','already','yet','ever','Already tugagan ishni ta’kidlaydi.']],wtask:'Safar tayyorgarligini just/already/yet bilan tekshirish xabarini yozing.',write:'Hi Lola, I have just finished packing. I have already put my notebook and water bottle in my bag. I haven’t printed the timetable yet, but I will do it tonight. Have you bought your ticket yet? I have never visited Khiva, so I am excited to see the old city with our class.',speak:'Tayyorgarlik bo‘yicha savollar bering va qilingan/qilinmagan ishlarni ayting.'}),
make('A2',13,{t:'Since, for va o‘tgan vaqtni tanlash',goal:'Davomiylikni boshlanish nuqtasidan ajratasiz va Perfect/Simple ni mos tanlaysiz.',context:'To‘garak a’zoligi va kechagi uchrashuv haqida yoziladi.',rule:['For davomiy muddat: for two years. Since boshlanish nuqtasi: since 2024. Bularni bir-birining o‘rnida ishlatmang.','Hali davom etayotgan holatda Present Perfect: I have lived here for two years. Kechagi tugallangan voqeada Past Simple.','Have been to — borib ko‘rgan, qaytgan tajriba. Have gone to — hozir u yerga ketgan degan farqni kontekstda tekshiring.'],pattern:'for two years / since 2024; have lived … / met yesterday',ex:['I have lived here for two years.','She has known Ali since 2024.','We met yesterday.','I joined the club last year.','I have been to Bukhara.','He has gone to the library.'],v:['since|… dan beri|/sɪns/|since Monday','for|davomida|/fɔː/|for two years','join|qo‘shilmoq|/dʒɔɪn/|join a club','member|a’zo|/ˈmembə/|a club member'],read:'I joined our English club last year. I have been a member for twelve months, and I have known our teacher since September. Yesterday we met in the library and discussed a travel story. I have been to Bukhara, so I shared one memory. Ali has gone to the library now to return a book; he will come back later. Our group has studied together since autumn, but we did not meet during the school holiday.',rq:[['Kecha nima qilishdi?','discussed a travel story','joined a new club','travelled to Bukhara','Yesterday … discussed — tugallangan voqea.'],['Ali hozir qayerga ketgan?','the library','Bukhara','the park','Has gone to the library, keyin qaytadi.']],listen:'I have been in the club for twelve months. I have known the teacher since September. We met yesterday. Ali has gone to the library and will come back later.',lq:[['A’zolik muddati qancha?','twelve months','two weeks','six years','For twelve months.'],['Ustozni qachondan taniydi?','September','yesterday','last night','Since September.']],table:[['Muddat','twelve months'],['Boshlanish','September']],gap:'I have known her ___ 2024.|since',fix:'I have lived here since two years.|I have lived here for two years.',mc:['Tugallangan vaqt uchun mos gap?','We met yesterday.','We have met yesterday.','We has met yesterday.','Yesterday bilan Past Simple.'],exit:[['___ two years','for'],['___ Monday','since'],['I ___ the club last year. (join)','joined'],['Gone to nimani bildirishi mumkin?','away there now','always returned','never visited','Kontekstda hali qaytmagan.'],['Been to tajriba gapimi?','Yes','No','Only a future plan','Borib ko‘rgan tajribasi.']],wtask:'Bir mashg‘ulotga qachon qo‘shilganingiz va qancha vaqtdan beri qatnashayotganingizni yozing.',write:'I joined the reading club last September. I have been a member for a year. I have known our teacher since the first meeting. Yesterday we discussed a story about a journey. I have been to Bukhara once, so I shared a memory. Our group has learned many useful words, and I still enjoy the meetings.',speak:'For va since bilan ikki davomiylikni ayting, keyin aniq o‘tgan kun voqeasini qo‘shing.',visual:'timeline'}),
make('A2',14,{t:'Zero va First Conditional',goal:'Odatdagi natija bilan mumkin bo‘lgan kelajak shartini ajratasiz.',context:'Sinf sayrining ob-havoga bog‘liq rejasi tuziladi.',rule:['Zero Conditional odatiy yoki umumiy natija: If you heat ice, it melts. If + Present Simple, Present Simple.','First Conditional real kelajak ehtimoli: If it rains, we will stay inside. If qismida odatda will emas, Present Simple keladi.','Shart qismi avval kelsa vergul ishlatiladi. We will stay inside if it rains shaklida odatda vergul kerak emas. Umumiy hodisani shaxsiy rejadan farqlang.'],pattern:'If + present, present / If + present, will + verb',ex:['If you heat ice, it melts.','If it rains, we will stay inside.','We will walk if the weather is good.','If you press this button, the light comes on.','If Ali arrives early, he will help us.','I will call you if the plan changes.'],v:['melt|erimoq|/melt/|ice melts','press|bosmoq|/pres/|press a button','change|o‘zgarmoq|/tʃeɪndʒ/|the plan changes','weather|ob-havo|/ˈweðə/|good weather'],read:'We are planning a science walk on Saturday. If the weather is good, we will visit the park and draw plants. If it rains, we will stay in the classroom and use photos. Our teacher shows us a lamp for the indoor activity. If you press its button, the light comes on. That is how the lamp normally works. Ali will bring paper if he arrives early. We will send everyone a message if the meeting place changes.',rq:[['Yomg‘ir yog‘sa nima qilishadi?','stay in the classroom','cancel all learning','walk farther','If it rains, we will stay in the classroom.'],['Lamp haqidagi gap nimani aytadi?','a usual result','an impossible wish','a past event','Press button → light comes on odatiy natija.']],listen:'If it rains on Saturday, we will stay inside. If the weather is good, we will visit the park. Press the lamp button: if you press it, the light comes on. I will call you if our plan changes.',lq:[['Yaxshi ob-havoda qayerga?','the park','the café','the station','Will visit the park.'],['Reja o‘zgarsa qanday xabar?','a call','a letter next month','no message','I will call you.']],table:[['Sayr kuni','Saturday'],['Yaxshi ob-havodagi joy','park']],gap:'If it ___, we will stay inside. (rain)|rains',fix:'If it will rain, we will stay inside.|If it rains, we will stay inside.',mc:['Umumiy natijani tanlang.','If you heat ice, it melts.','If you heated ice, yesterday.','If ice will melts.','Zero conditional umumiy qonuniyat.'],exit:[['If she ___ early, she will help. (arrive)','arrives'],['We ___ call you if it changes.','will'],['If you heat ice, it ___.','melts'],['If qismiga odatda qaysi zamon?','Present Simple','will + verb','Past Perfect always','Real kelajak shartida present.'],['Umumiy natija qaysi?','Zero Conditional','only Past Simple','only a question','Zero odatiy natija.']],wtask:'Tadbir uchun ikkita shartli reja va bir odatiy natija yozing.',write:'If the weather is good, our class will visit the park. If it rains, we will work in the library. I will bring paper if we need to draw. The teacher will send a message if the meeting place changes. For our science activity, if you put ice in a warm room, it slowly melts.',speak:'Sherigingiz bilan ikki ehtimol uchun reja kelishing.',visual:'cause'}),
make('A2',15,{t:'Gerund va infinitive: niyat va yoqtirish',goal:'Enjoy doing va want to do kabi qoliplarni ajratasiz.',context:'O‘quvchi yangi to‘garak va til maqsadini tanlaydi.',rule:['Enjoy, finish, avoid kabi fe’llardan keyin -ing; want, plan, decide dan keyin to + asosiy fe’l ko‘p ishlatiladi.','Bitta umumiy qoida barcha fe’llarni qamramaydi. Fe’lni keyingi qolipi bilan o‘rganing: enjoy reading, decide to join.','Like doing va like to do ayrim vaziyatlarda ikkalasi ham mumkin. Enjoy to do esa standart emas. Xatoni aynan bosh fe’lga qarab tekshiring.'],pattern:'enjoy doing / want to do / decide to join',ex:['I enjoy reading stories.','She wants to join the club.','We decided to study together.','He finished writing the email.','They plan to visit Bukhara.','I avoid using my phone in class.'],v:['decide|qaror qilmoq|/dɪˈsaɪd/|decide to join','avoid|chetlab o‘tmoq|/əˈvɔɪd/|avoid using','plan|rejalashtirmoq|/plæn/|plan to visit','join|qo‘shilmoq|/dʒɔɪn/|join a club'],read:'Lola enjoys reading, but she wants to improve her speaking too. She decides to join the English club. Ali plans to study with her twice a week. They finish writing their first short email and then practise a dialogue. During study time, they avoid using their phones for games. Their teacher asks them to choose a small goal, such as learning to ask for directions. They do not try to learn everything in one evening. A clear plan helps them practise regularly.',rq:[['Lola nimani rivojlantirmoqchi?','speaking','only spelling','football','Wants to improve her speaking too.'],['Nimadan qochishadi?','phone games during study','all group work','reading stories','Avoid using phones for games.']],listen:'I enjoy reading, but I want to improve my speaking. I decided to join the club. Ali plans to study with me. We avoid using our phones for games while we study.',lq:[['So‘zlovchi nimani yoqtiradi?','reading','dancing','driving','Enjoy reading.'],['Nimaga qo‘shilishga qaror qildi?','the club','the bus company','a football team','Decided to join the club.']],table:[['Yoqtiradigan ish','reading'],['Rivojlantiradigan ko‘nikma','speaking']],gap:'She wants ___ join the club.|to',fix:'I enjoy to read.|I enjoy reading.',mc:['Decide bilan mos qolip?','decide to join','decide joining (ordinary intention)','decide joins','Decide to do — qaror.'],exit:[['He finished ___ the email. (write)','writing'],['They plan ___ visit Bukhara.','to'],['I avoid ___ my phone. (use)','using'],['Want bilan qaysi shakl?','to improve','improving only','improves','Want to improve.'],['Enjoy reading to‘g‘rimi?','Yes','No','Only in questions','Enjoy + -ing.']],wtask:'Til o‘rganish rejangiz: yoqtiradigan ish, niyat, qaror va qochmoqchi odat haqida yozing.',write:'I enjoy watching short English videos, but I want to speak more confidently. I plan to practise with a friend twice a week. We decided to record a short dialogue and listen to it again. I avoid using my phone for games during study time. After finishing each exercise, I check why my answer was right or wrong.',speak:'Bir niyat va uni bajarish qarorini tushuntiring.'}),
make('A2',16,{t:'Somebody, anything va nowhere',goal:'Noma’lum odam, narsa yoki joy haqida gapirasiz.',context:'Kutubxonada qolgan sumkaning egasi qidiriladi.',rule:['Someone/somebody — kimdir; something — nimadir; somewhere — qayerdir. Bu so‘zlar ko‘pincha tasdiqda.','Anyone/anything/anywhere savol va inkorda ko‘p uchraydi. Nobody/nothing/nowhere o‘zi inkor, qo‘shimcha not talab qilmaydi.','Someone va everyone grammatik birlik: Everyone is here. They ko‘pincha jinsi noma’lum shaxsga keyingi gapda neytral murojaat qiladi.'],pattern:'Someone is … / I didn’t see anyone. / Nobody is …',ex:['Someone left a bag here.','Does anyone know the owner?','I didn’t see anything inside.','Nobody is in the room.','Everyone is ready.','We can put it somewhere safe.'],v:['owner|ega|/ˈəʊnə/|the bag’s owner','safe|xavfsiz|/seɪf/|somewhere safe','inside|ichida|/ɪnˈsaɪd/|look inside','everyone|hamma|/ˈevriwʌn/|everyone is ready'],read:'Someone left a blue bag in the library. The librarian asks if anyone knows the owner. Nobody in the room recognises it. There is something written on a label, but the name is difficult to read. The librarian does not open the bag. She puts it somewhere safe and tells the school office. Later, a student comes back for it. They describe the bag and show the same name on their notebook. Everyone is pleased that the bag is returned safely.',rq:[['Kutubxonachi sumkani ochdimi?','No','Yes','Only the first pocket','Does not open the bag.'],['Ega nima bilan tasdiqlanadi?','description and matching name','guessing its colour only','finding money','Describe the bag and show the same name.']],listen:'Someone left a blue bag. Does anyone know the owner? Nobody here recognises it. We will put it somewhere safe and tell the school office. Please don’t open it.',lq:[['Sumka rangi?','blue','black','green','Blue bag.'],['Kimga xabar beriladi?','school office','a shop','the bus driver','Tell the school office.']],table:[['Rang','blue'],['Xabar joyi','school office']],gap:'Everyone ___ ready.|is',fix:'Nobody isn’t here.|Nobody is here.',mc:['Inkor gapni to‘ldiring: I didn’t see ___.','anyone','no one (double negative)','everyone is','Any inkor bilan mos.'],exit:[['___ left a bag. (kimdir)','Someone'],['Everyone ___ here.','is'],['I didn’t see ___. (hech kimni)','anyone'],['Nobody bilan not qo‘shish kerakmi?','No','Yes','Always','Nobody o‘zi inkor.'],['Somewhere safe nimani bildiradi?','a safe place','a known person','every object','Somewhere joy.']],wtask:'Topilgan buyum haqida uning shaxsiy ichidagi ma’lumotni ochmasdan e’lon yozing.',write:'Someone left a blue bag in the library today. Nobody in our group knows the owner. The bag is now somewhere safe in the school office. Please ask a teacher if it is yours. You should describe the bag and show your name. Do not share anyone’s private information in the class chat.',speak:'Topilgan buyum egasini aniqlash uchun savollar bering.'}),
make('A2',17,{t:'Yo‘nalishlar va kundalik phrasal verbs',goal:'Turn left, get on/off, pick up bilan yo‘l va vazifani tushuntirasiz.',context:'Yangi sinfdosh kutubxonaga avtobus bilan boradi.',rule:['Turn left/right, go straight, cross the road yo‘nalish buyruqlaridir. Across bir tomondan ikkinchisiga, along esa yo‘l bo‘ylab.','Get on/off avtobus yoki poyezdga chiqish/tushish. Pick up buyumni olish yoki odamni olib ketish bo‘lishi mumkin. Ma’noni vaziyat beradi.','Pick the book up / pick up the book mumkin, ammo olmosh o‘rtada: pick it up. Get on the bus kabi ajralmaydigan qolip bilan farqlang.'],pattern:'go straight / turn left / get off / pick it up',ex:['Go straight and turn left.','Get on the bus at this stop.','Get off near the library.','Walk across the road carefully.','Please pick it up.','We set off at nine.'],v:['turn left|chapga burilmoq|/tɜːn left/|turn left at the bank','get off|tushmoq|/ɡet ɒf/|get off the bus','pick up|olmoq, olib ketmoq|/pɪk ʌp/|pick it up','across|narigi tomoniga|/əˈkrɒs/|across the road'],read:'To reach the library, get on bus 4 at the school stop. Get off at the bank. Walk across the road at the crossing, then go straight for two minutes. Turn left at the bookshop. The library is next to a small park. Lola will pick you up at the library entrance if you cannot find the room. Bring your notebook, and remember to pick it up before you leave. Our group sets off for the museum at nine the next morning.',rq:[['Qayerda avtobusdan tushiladi?','at the bank','at the school','at the museum','Get off at the bank.'],['Olmosh bilan mos tartib qaysi?','pick it up','pick up it','it pick up','Ajraladigan qolipda olmosh o‘rtada.']],listen:'Get on bus four at school. Get off at the bank. Cross the road safely and go straight. Turn left at the bookshop. The library is next to the park.',lq:[['Avtobus raqami?','four','two','nine','Bus four.'],['Qayerda chapga buriladi?','at the bookshop','at school','in the park','Turn left at the bookshop.']],table:[['Avtobus','4'],['Tushish joyi','bank']],gap:'Please pick ___ up. (it)|it',fix:'Pick up it.|Pick it up.',mc:['Avtobusdan tushmoq uchun ibora?','get off','get on','go up','Get off transportdan tushish.'],exit:[['Turn ___. (chapga)','left'],['Get ___ the bus. (tushmoq)','off'],['Pick ___ up. (it)','it'],['Roadning narigi tomoniga o‘tish?','across','along only','inside','Across — bir tomondan boshqasiga.'],['Boshlash, yo‘lga chiqish iborasi?','set off','turn off always','pick it','Set off — yo‘lga chiqmoq.']],wtask:'Maktabdan bir manzilgacha xavfsiz yo‘l ko‘rsatmasini yozing.',write:'Get on bus 4 at the school stop and get off at the bank. Cross the road at the crossing. Go straight for two minutes, then turn left at the bookshop. The library is next to the park. I will pick you up at the entrance. Please bring your notebook and pick it up before you leave.',speak:'Xaritada sherigingizni manzilga olib boring; u yo‘lni qayta aytsin.',visual:'map'}),
make('A2',18,{t:'Paragraf va sayohat loyihasi',goal:'O‘tgan safar, hozirgi tajriba va keyingi rejani bog‘langan xabarda aytasiz.',context:'Do‘stingizga birinchi mustaqil ekskursiya haqida email yozasiz.',rule:['Paragrafda bitta asosiy fikr bo‘lsin. First/then/finally vaqt tartibi, because sabab, but farqni bog‘laydi.','O‘tgan aniq voqeada Past Simple, hozirgi tajribada Present Perfect, reja uchun going to ishlatilishini qayta tekshiring.','Emailda salomlashish, asosiy xabar va yakun bo‘lsin. Keraksiz qayta takrorni kamaytiring, lekin muhim joy va vaqtni tushirib qoldirmang.'],pattern:'Greeting → what happened → why it mattered → next plan → closing',ex:['Last Saturday we visited Bukhara.','First, we met our guide.','Then we walked around the old town.','I have never seen that building before.','We are going to return next year.','Please tell me about your trip.'],v:['guide|gid|/ɡaɪd/|meet a guide','return|qaytmoq|/rɪˈtɜːn/|return next year','trip|safar|/trɪp/|a memorable trip','before|oldin|/bɪˈfɔː/|never seen before'],read:'Hi Ali, last Saturday our class visited Bukhara. First, we met a guide at the station. Then we walked around the old town and drew one building. I had never noticed how many different patterns a wall could have. At lunch, I lost my bottle, but a classmate found it. I have kept the drawing in my notebook because it reminds me of the day. We are going to return next year and visit the museum too. What did you do last weekend? Best wishes, Lola.',rq:[['Matnning asosiy maqsadi nima?','sharing a trip and asking about a friend','selling a bottle','giving museum rules','Email o‘z safarini aytib do‘stiga savol beradi.'],['Nima uchun chizmani saqlagan?','it reminds her of the day','the guide bought it','it is a ticket','Because it reminds me of the day.']],listen:'Last Saturday we visited Bukhara. First, we met our guide. Then we walked around the old town. A classmate found my bottle. We are going to return next year and visit the museum.',lq:[['Safar qachon bo‘lgan?','last Saturday','next year','this morning','Last Saturday — tugallangan vaqt.'],['Keyingi yil nima qo‘shiladi?','the museum','a shopping centre','the airport','Visit the museum.']],table:[['Shahar','Bukhara'],['Keyingi joy','museum']],gap:'Last Saturday we ___ Bukhara. (visit)|visited',fix:'Yesterday we have visited Bukhara.|Yesterday we visited Bukhara.',mc:['Paragraf uchun eng foydali qoida qaysi?','Keep one main idea and connect details.','Write every sentence without a link.','Repeat one sentence many times.','Bog‘lanish va bitta asosiy fikr.'],exit:[['First, we ___ our guide. (meet)','met'],['We are ___ to return.','going'],['I keep it ___ it reminds me of the day.','because'],['Aniq o‘tgan vaqtga mos shakl?','visited last Saturday','have visited last Saturday','will visited last Saturday','Past Simple.'],['Email yakuniga mos ibora?','Best wishes','Room 5 only','Did you are','Best wishes do‘stona yakun.']],wtask:'A2 loyiha: safar yoki o‘tgan voqea haqida do‘stona email yozing; keyingi rejani va bir savolni qo‘shing.',write:'Hi Ali, last Saturday we visited a small village near our town. First, we met our cousins. Then we walked to the river and took photos. I enjoyed the day because the village was quiet. I have kept my favourite photo in my notebook. We are going to visit again in spring. What did you do last weekend? Best wishes, Lola.',speak:'Safar hikoyangizni ayting, keyingi rejangizni tushuntiring va sherigingizga savol bering.',real:'Sayr bo‘yicha uch ma’lumotni oling, emailga qo‘shing va sherigingizdan uning rejasini so‘rang.',visual:'story'})
];
